/**
 * Tests for no-batch-insert-loop
 * CWE-1049 — Prevent executing database queries within loops (N+1 problem).
 *
 * Generated by: node scripts/generate-rule-tests.mjs
 * Standard: Engineering Standards §5 (side-by-side), §6 (≥5 valid + ≥5 invalid), §8 (RuleTester at describe level)
 */
import { RuleTester } from '@typescript-eslint/rule-tester';
import { describe, it, afterAll } from 'vitest';
import parser from '@typescript-eslint/parser';
import { noBatchInsertLoop } from './index';

/**
 * Every fixture imports a PostgreSQL client, because the rule now abstains in
 * files that use no PostgreSQL at all. Wrapping the arrays rather than editing
 * each fixture means one cannot be left behind — a fixture missing the import
 * would pass vacuously on the gate instead of exercising the detection it was
 * written for.
 */
const withPg = (code: string): string => `import { Pool } from 'pg';\n${code}`;
const pg = <T,>(cases: T[]): T[] =>
  cases.map((c) =>
    typeof c === 'string'
      ? (withPg(c) as T)
      : ({ ...c, code: withPg((c as { code: string }).code) } as T),
  );


RuleTester.afterAll = afterAll;
RuleTester.it = it;
RuleTester.itOnly = it.only;
RuleTester.describe = describe;

const ruleTester = new RuleTester({
  languageOptions: {
    parser,
    ecmaVersion: 2022,
    sourceType: 'module',
    parserOptions: { ecmaFeatures: { jsx: true } },
  },
});

describe('no-batch-insert-loop', () => {
  describe('Valid Code', () => {
    ruleTester.run('valid - safe patterns', noBatchInsertLoop, {
      valid: pg([
        // Unrelated code should not trigger
        {
          name: 'pg is imported but nothing queries',
          code: `const x = 1;`,
        },
        // Array operations are safe
        {
          code: `const arr = [1, 2, 3];`,
        },
        // Non-targeted method calls are safe
        {
          code: `obj.safeMethod();`,
        },
        // Environment variable usage is safe (padding case 4)
        {
          code: `const safe3 = process.env.DB_HOST;`,
        },
        // Environment variable usage is safe (padding case 5)
        {
          code: `const safe4 = process.env.DB_HOST;`,
        },
      ]),
      invalid: [],
    });
  });

  describe('Invalid Code', () => {
    ruleTester.run('invalid - dangerous patterns', noBatchInsertLoop, {
      valid: [],
      invalid: pg([
        // Triggers noBatchInsertLoop
        {
          name: 'one INSERT round-trip per item in the loop',
          code: `for (const item of items) { client.query('INSERT INTO t(a) VALUES($1)', [item]); }`,
          errors: [{ messageId: 'noBatchInsertLoop' }],
        },
      ]),
    });
  });
});

/**
 * REGRESSION LOCKS — every defect the rule corpus
 * (`benchmarks/rule-corpus/postgresql-security__no-batch-insert-loop`) proved.
 *
 * BEFORE: TP 9 / FP 2 / FN 1 — precision 81.8%, recall 90.0%, F1 85.7%.
 * AFTER:  14 / 0 / 0 — 100% on the corpus including the adversarial wave.
 */
describe('no-batch-insert-loop — regression locks', () => {
  ruleTester.run('the statement kind is not a filter', noBatchInsertLoop, {
    valid: [],
    invalid: pg([
      {
        // The N+1 problem by its textbook definition: one parent query, then
        // one child SELECT per parent row. The rule used to return unless the
        // SQL contained INSERT or UPDATE.
        code: "async function f() { for (const o of orders) { await pool.query('SELECT id FROM lines WHERE order_id = $1', [o.id]); } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        // The filter only ran on a plain string, so the identical statement
        // reported in one spelling and not the other.
        code: 'async function f() { for (const s of shards) { await pool.query(`SELECT id FROM t WHERE shard = $1`, [s]); } }',
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
    ]),
  });

  ruleTester.run('loop and callback shapes', noBatchInsertLoop, {
    valid: [],
    invalid: pg([
      {
        code: "async function f() { for (const k in counters) { await pool.query('UPDATE m SET v = $1 WHERE n = $2', [counters[k], k]); } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        code: "async function f() { let i = 0; do { await pool.query('UPDATE t SET a = 1 WHERE id = $1', [i]); i++; } while (i < 3); }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        code: "async function f() { for await (const e of stream) { await pool.query('INSERT INTO e (id) VALUES ($1)', [e.id]); } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        code: "async function f() { outer: for (const b of batches) { for (const r of b.rows) { await pool.query({ text: 'UPDATE l SET x = $1 WHERE id = $2', values: [r.x, r.id] }); } } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        code: "async function f() { for (;;) { const m = q.pop(); if (!m) break; await pool.query('INSERT INTO d (id) VALUES ($1)', [m.id]); } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        // The walk has to pass through `.then` to find the `reduce` above it.
        code: "statements.reduce((chain, s) => chain.then(() => pool.query('INSERT INTO log (s) VALUES ($1)', [s])), Promise.resolve());",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        // A `map` nested inside a real loop. Treating `map` as a value
        // producer must not make the enclosing loop invisible.
        code: "async function f() { for (const t of tenants) { await Promise.all(t.skus.map(s => pool.query('UPDATE p SET t = $1 WHERE sku = $2', [t.id, s]))); } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        // A concurrent fan-out is not a licence for what happens inside each
        // callback.
        code: "async function f() { await Promise.all(groups.map(async g => { for (const r of g.rows) { await pool.query('INSERT INTO gr (g, r) VALUES ($1, $2)', [g.id, r.id]); } })); }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        // LIMIT alone under a loop that iterates a COLLECTION is an ordinary
        // N+1 — the pagination carve-out must not reach it.
        code: "async function f() { for (const u of users) { await pool.query('SELECT id FROM t WHERE u = $1 ORDER BY at DESC LIMIT 1', [u]); } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
    ]),
  });

  ruleTester.run('shapes that are not an N+1', noBatchInsertLoop, {
    valid: pg([
      // `map` PRODUCES an array of promises and whoever consumes it decides
      // the concurrency. `Promise.all(xs.map(...))` is the shape people write
      // to escape sequential round trips — reporting it fires on the fix — and
      // the carve-out must survive the indirection through a binding.
      "async function f() { await Promise.all(ids.map(id => pool.query('SELECT id FROM t WHERE id = $1', [id]))); }",
      { name: 'a map of reads bound to a const and awaited by Promise.all is the concurrency fix', code: "async function f() { const pending = ids.map(id => pool.query('SELECT 1')); await Promise.all(pending); }" },
      // A lambda the loop STORES rather than invokes. `push` stores, `map`
      // invokes; "the parent is a call" cannot tell them apart.
      "for (const a of accounts) { jobs.push(() => pool.query('UPDATE a SET s = now() WHERE id = $1', [a.id])); }",
      // Pagination: one statement per PAGE. LIMIT with OFFSET is unambiguous;
      // LIMIT alone counts under `while`/`do…while`, which iterate a condition
      // rather than a collection.
      "async function f() { while (true) { const { rows } = await pool.query('SELECT id FROM u ORDER BY id LIMIT $1 OFFSET $2', [500, o]); if (!rows.length) break; } }",
      "async function f() { while (true) { const { rows } = await pool.query('SELECT id FROM u WHERE id > $1 ORDER BY id LIMIT $2', [last, 500]); if (!rows.length) break; } }",
      // The loop builds arrays; one statement runs after it.
      "async function f() { const e = []; for (const r of rs) { e.push(r.email); } await pool.query('INSERT INTO u (e) SELECT * FROM unnest($1::text[])', [e]); }",
      // The sink is `query`, not "a method on a database handle".
      "async function f() { for (const c of clients) { c.release(); } }",
      "for (const r of rows) { totals.set(r.kind, r.amount); }",
      // Intra-procedural by design: blaming a callee would report every
      // repository method anybody ever calls twice.
      "async function insertOne(r) { await pool.query('INSERT INTO u (e) VALUES ($1)', [r.email]); }",
      // A function body is not a loop.
      "router.get('/u/:id', async (req, res) => { const { rows } = await pool.query('SELECT id FROM u WHERE id = $1', [req.params.id]); res.json(rows[0]); });",
    ]),
    invalid: [],
  });
});

/**
 * Coverage of the walk's stopping conditions and of the pagination reader.
 */
describe('no-batch-insert-loop — walk boundaries', () => {
  ruleTester.run('function relationships', noBatchInsertLoop, {
    valid: [
      // No PostgreSQL client in the file: the plugin does not run at all.
      "for (const i of items) { db.query('INSERT INTO t VALUES ($1)', [i]); }",
      ...pg([
        // An IIFE runs exactly once where it is written, so it is transparent
        // rather than a boundary — and there is no loop above this one.
        "(async () => { await pool.query('INSERT INTO t VALUES (1)'); })();",
        // A callback whose callee is not a member call says nothing about how
        // often it runs.
        "setTimeout(async () => { await pool.query('INSERT INTO t VALUES (1)'); }, 1000);",
      ]),
    ],
    invalid: pg([
      {
        // …and the same IIFE inside a loop still reports, because the walk
        // passes through it.
        code: "async function f() { for (const i of items) { await (async () => { await pool.query('INSERT INTO t VALUES ($1)', [i]); })(); } }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        // Arguments the pagination reader cannot interpret fall through to a
        // report: the evidence for this rule is the loop, not the SQL.
        code: 'async function f() { for (const i of items) { await pool.query(123); } }',
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        code: 'async function f() { for (const i of items) { await pool.query({ values: [i] }); } }',
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        code: 'async function f() { for (const i of items) { await pool.query(sql, [i]); } }',
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
    ]),
  });
});

/** FP/FN review 2026-10 (benchmarks/audits/2026-10-10-fp-fn-postgresql-security.md). */
describe('no-batch-insert-loop — fp/fn review 2026-10', () => {
  ruleTester.run('BIL-1: an already-batched statement in a chunk loop', noBatchInsertLoop, {
    valid: pg([
      {
// @found harness-reproduced FP/FN audit 2026-10-10 (benchmarks/audits/2026-10-10-fp-fn-postgresql-security.md)
 name: 'FP: a chunk loop over an unnest batch insert is the rule\'s own suggested fix', code: "const pool = new Pool();\nfor (const batch of chunks) { await pool.query('INSERT INTO users (email, name) SELECT * FROM unnest($1::text[], $2::text[])', [batch.map((u) => u.email), batch.map((u) => u.name)]); }" },
      {
// @found reasoned during the 2026-10-10 FP/FN audit, not seen in real code
 name: 'FP: a chunk loop over a pg-format %L batch insert is already batched', code: "const pool = new Pool();\nfor (const batch of chunks) { await pool.query(format('INSERT INTO t (a, b) VALUES %L', batch)); }" },
      {
// @found reasoned during the 2026-10-10 FP/FN audit, not seen in real code
 name: 'FP: a chunk loop over a jsonb_to_recordset batch insert is already batched', code: "const pool = new Pool();\nfor (const batch of chunks) { await pool.query({ text: 'INSERT INTO t SELECT * FROM jsonb_to_recordset($1) AS x(a int)', values: [JSON.stringify(batch)] }); }" },
    ]),
    invalid: pg([
      {
        name: 'a statement built by a call with no arguments is unreadable, so reported',
        code: 'const pool = new Pool();\nfor (const r of rows) { await pool.query(build()); }',
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        name: 'one row per round trip is still N+1',
        code: "const pool = new Pool();\nfor (const r of rows) { await pool.query('INSERT INTO t (a) VALUES ($1)', [r.a]); }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
    ]),
  });

  ruleTester.run('BIL-2: keyset pagination in for(;;)', noBatchInsertLoop, {
    valid: pg([
      {
// @found harness-reproduced FP/FN audit 2026-10-10 (benchmarks/audits/2026-10-10-fp-fn-postgresql-security.md)
 name: 'FP: keyset pagination with LIMIT in for(;;) is one query per page', code: "const pool = new Pool();\nfor (;;) { const { rows } = await pool.query('SELECT id FROM users WHERE id > $1 ORDER BY id LIMIT 1000', [last]); if (!rows.length) break; last = rows.at(-1).id; }" },
    ]),
    invalid: pg([
      {
        name: 'a counted for loop with LIMIT is not pagination',
        code: "const pool = new Pool();\nfor (let i = 0; i < ids.length; i++) { await pool.query('SELECT id FROM users WHERE id = $1 LIMIT 1', [ids[i]]); }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
    ]),
  });

  // Moved here from 'shapes that are not an N+1' (it was a VALID case). A
  // per-row UPDATE inside `.map()` issues one statement per element whatever
  // awaits the array — `UPDATE p SET r = now() WHERE sku = ANY($1)` is the
  // batched form — and the rule's own docs list the `.map` write as Incorrect.
  ruleTester.run('BIL-3: a per-row UPDATE through allSettled(map) is reported', noBatchInsertLoop, {
    valid: [],
    invalid: pg([
      {
// @found reasoned during the 2026-10-10 FP/FN audit, not seen in real code

          name: 'FN: a per-row UPDATE through Promise.allSettled(map) is one round trip per element',
        code: "async function f() { return Promise.allSettled(skus.map(s => pool.query('UPDATE p SET r = now() WHERE sku = $1', [s]))); }",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
    ]),
  });

  ruleTester.run('BIL-3: a write inside .map() is one round trip per element', noBatchInsertLoop, {
    valid: pg([
      // Concurrent reads through the pool stay the documented trade-off.
      { name: 'concurrent reads through Promise.all(map) stay the documented trade-off', code: "const pool = new Pool();\nawait Promise.all(ids.map((id) => pool.query('SELECT id, name FROM users WHERE id = $1', [id])));" },
      { name: 'an unreadable statement inside map is not treated as a write', code: "const pool = new Pool();\nawait Promise.all(ids.map((id) => pool.query(sqlFor(id))));" },
    ]),
    invalid: pg([
      {
        name: 'the docs’ own Incorrect example',
        code: "users.map((user) => client.query('INSERT INTO users VALUES ($1)', [user.id]));",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        name: 'Promise.all over per-item INSERTs on one client',
        code: "await Promise.all(items.map((it) => client.query('INSERT INTO order_items (order_id, sku) VALUES ($1, $2)', [orderId, it.sku])));",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        name: 'Array.from with a mapper (the docs’ Known False Negative)',
        code: "const queries = Array.from(users, (u) => client.query('INSERT INTO users VALUES ($1)', [u.id]));\nawait Promise.all(queries);",
        errors: [{ messageId: 'noBatchInsertLoop' }],
      },
      {
        name: 'flatMap with UPDATE and DELETE',
        code: "items.flatMap((it) => [client.query({ text: 'UPDATE t SET a = 1 WHERE id = $1', values: [it] }), client.query(`DELETE FROM t WHERE id = $1`, [it])]);",
        errors: [{ messageId: 'noBatchInsertLoop' }, { messageId: 'noBatchInsertLoop' }],
      },
    ]),
  });

  ruleTester.run('FQ-2: a non-pg .query() in a pg-importing test file', noBatchInsertLoop, {
    valid: pg([
      {
// @found harness-reproduced FP/FN audit 2026-10-10 (benchmarks/audits/2026-10-10-fp-fn-postgresql-security.md)
 name: 'FP: supertest .query({ q }) in a loop is not a database query', code: "for (const term of terms) { await request(app).get('/users/search').query({ q: term }).expect(200); }" },
    ]),
    invalid: pg([]),
  });
});
